DROP TABLE IF EXISTS `validation_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `validation_requests` (
  `id` binary(16) NOT NULL,
  `request_id` varchar(64) NOT NULL,
  `event_id` binary(16) NOT NULL,
  `api_key_prefix` varchar(80) NOT NULL,
  `product_code` varchar(80) NOT NULL,
  `outcome` enum('valid','invalid','not_found','pending','provider_error','rate_limited','quota_exhausted','not_kyc') NOT NULL,
  `target_fingerprint` char(64) NOT NULL,
  `target_masked` varchar(120) NOT NULL,
  `provider_reference` varchar(255) DEFAULT NULL,
  `provider_latency_ms` bigint unsigned NOT NULL,
  `rajacek_processing_ms` bigint unsigned DEFAULT NULL,
  `total_latency_ms` bigint unsigned DEFAULT NULL,
  `attempts` int unsigned DEFAULT NULL,
  `occurred_at` datetime(6) NOT NULL,
